/* FORE service worker. Source: sw.template.js. docs/sw.js is generated by build.js, do not edit it. */
'use strict';

// Rule 2: the build version is stamped in here so the page can compare it
// against its own version before showing an update banner.
const VERSION = '0.1.52';
const PAGE_CACHE = 'fore-page-' + VERSION;
const ASSET_CACHE = 'fore-assets-' + VERSION;
const ASSETS = ["manifest.webmanifest","icon-180.png","icon-192.png","icon-512.png","sounds/draw.wav"];
const SCOPE = self.registration.scope;
const PAGE_KEY = new URL('index.html', SCOPE).href;
const NAV_TIMEOUT_MS = 1200;

function assetKey(url) {
  const u = new URL(url, SCOPE);
  u.search = '';
  u.hash = '';
  return u.href;
}
const ASSET_KEYS = new Set(ASSETS.map(assetKey));

// Rule 3: install waits on the page only. The asset sweep runs in its own
// waitUntil during activate, so closing the app mid-sweep cannot leave the
// new worker stuck in "installing" forever.
self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(PAGE_CACHE);
    // Rule 4: cache "reload" bypasses the HTTP cache so we never store a stale page.
    const res = await fetch(new Request(PAGE_KEY, { cache: 'reload' }));
    if (!res.ok) throw new Error('page fetch failed: ' + res.status);
    await cache.put(PAGE_KEY, res);
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(
      names
        .filter((n) => n.startsWith('fore-') && n !== PAGE_CACHE && n !== ASSET_CACHE)
        .map((n) => caches.delete(n))
    );
    await self.clients.claim();
  })());
  event.waitUntil(precacheAssets());
});

// Rule 4: fetch each asset with cache "reload" and store it under a fixed key.
// Never cache.addAll, which goes through the HTTP cache.
async function precacheAssets() {
  const cache = await caches.open(ASSET_CACHE);
  await Promise.all(ASSETS.map(async (rel) => {
    const key = assetKey(rel);
    if (await cache.match(key)) return;
    try {
      const res = await fetch(new Request(key, { cache: 'reload' }));
      if (res.ok) await cache.put(key, res);
    } catch (e) {
      // Offline or flaky. The page re-sends "precache" on every load, so we retry then.
    }
  }));
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    event.respondWith(freshFirstPage());
    return;
  }
  if (ASSET_KEYS.has(assetKey(req.url))) {
    event.respondWith(cachedAsset(req));
  }
});

// Rule 1: fresh-first navigation. Fetch the page with cache "no-store" and
// race it against the stored copy with a timeout. Serve whichever wins,
// and always write the fresh copy back when it arrives.
async function freshFirstPage() {
  const cache = await caches.open(PAGE_CACHE);
  const network = fetch(new Request(PAGE_KEY, { cache: 'no-store' })).then(async (res) => {
    if (!res.ok) throw new Error('page status ' + res.status);
    await cache.put(PAGE_KEY, res.clone());
    return res;
  });
  const first = await Promise.race([
    network.then((res) => ({ kind: 'net', res }), () => ({ kind: 'neterr' })),
    new Promise((resolve) => setTimeout(() => resolve({ kind: 'timeout' }), NAV_TIMEOUT_MS)),
  ]);
  if (first.kind === 'net') return first.res;
  const cached = await cache.match(PAGE_KEY);
  if (cached) return cached;
  // Nothing stored yet, so the network is the only option left.
  try {
    return await network;
  } catch (e) {
    return new Response('FORE is offline and has not been cached yet. Open it once with a connection.', {
      status: 503,
      headers: { 'content-type': 'text/plain; charset=utf-8' },
    });
  }
}

async function cachedAsset(req) {
  const cache = await caches.open(ASSET_CACHE);
  const key = assetKey(req.url);
  const hit = await cache.match(key);
  if (hit) return hit;
  try {
    const res = await fetch(new Request(key, { cache: 'reload' }));
    if (res.ok) await cache.put(key, res.clone());
    return res;
  } catch (e) {
    return new Response('', { status: 504 });
  }
}

self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type === 'version' && event.source) {
    event.source.postMessage({ type: 'version', version: VERSION });
  } else if (data.type === 'precache') {
    event.waitUntil(precacheAssets());
  }
});
